    @Test void currentRecoveryRoundTripsACommittedEmptySchemaAfterDeletingTheLastColumn() {
        var member=new ReplicaDescriptor(new UUID(990,1),new UUID(990,2),new UUID(990,3),"current-receiver","127.0.0.1:4598",ReplicaDescriptor.Role.VOTER);
        var schema=new DistributedSchema(new UUID(991,1),new UUID(991,2),new UUID(991,3),2,0,List.of());
        var range=new RangeDescriptor(new UUID(992,1),new UUID(992,2),1,0,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(member));
        var directory=new RangeDirectory(schema.clusterId(),schema.databaseId(),schema.domainId(),schema.schemaEpoch(),schema.digest(),3,Set.of(),0,List.of(range));
        var original=new NativeCurrentRangeRecovery(new UUID(993,1),new UUID(993,2),new ApplyPosition(1,8),directory,schema,range.groupId(),member,member,new ApplyPosition(1,5),new byte[32],0,-1,new byte[]{1},null,Map.of(),Set.of(),Map.of());
        var decoded=NativeCurrentRangeRecovery.decode(original.encode());
        assertEquals(original,decoded);assertArrayEquals(original.encode(),decoded.encode());
        assertTrue(decoded.schema().columns().isEmpty());assertTrue(decoded.physicalNames().isEmpty());assertTrue(decoded.mergeColumns().isEmpty());assertEquals(range,decoded.range());
    }

